<template>
    <div id="bk" class="wrapper">
        <div class="login-box">
            <div class="title">
                <b>注 册</b>
            </div>
            <div style="margin-top: 30px">
                <el-form label-width="70px">
                    <el-form-item label="用户名">
                        <el-input
                            v-model.trim="user.username"
                            aria-required="true"
                        ></el-input>
                    </el-form-item>
                    <el-form-item label="联系方式" style="margin-top: 25px">
                        <el-input
                            v-model.trim="user.phone"
                            aria-required="true"
                        ></el-input>
                    </el-form-item>
                    <el-form-item label="密码" style="margin-top: 25px">
                        <el-input
                            v-model.trim="user.password"
                            show-password
                            aria-required="true"
                        ></el-input>
                    </el-form-item>
                    <el-form-item label="确认密码" style="margin-top: 25px">
                        <el-input
                            v-model.trim="user.confirmPassword"
                            show-password
                            aria-required="true"
                        ></el-input>
                    </el-form-item>
                    <el-form-item style="text-align: center;">
                        <el-button
                            type="success"
                            @click="onSubmit"
                            style="font-size: 22px"
                        >
                             注册</el-button
                        >
                        <el-button
                            @click="$router.push('/login')"
                            style="font-size: 22px"
                        >
                             返回登录</el-button
                        >
                    </el-form-item>
                </el-form>
            </div>
        </div>
    </div>
</template>

<script>
import md5 from "js-md5";


export default {
    name: "Login",
    data() {
        return {
            user: {},
            passwordRule: /^(?=.*[A-Za-z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{}|;:,.<>?])[A-Za-z\d!@#$%^&*()_+\-=\[\]{}|;:,.<>?]{6,12}$/,
        };
    },
    methods: {
        onSubmit() {
            const username = (this.user.username || "").trim();
            const password = (this.user.password || "").trim();
            const confirmPassword = (this.user.confirmPassword || "").trim();
            const phone = (this.user.phone || "").trim();

            if (!username || !password || !confirmPassword) {
                this.$message.error("用户名或密码不能为空");
                return false;
            }
            if (!this.passwordRule.test(password)) {
                this.$message.error("密码必须为6-12位，且同时包含字母、数字和特殊符号");
                return false;
            }
            if (!phone) {
                this.$message.error("联系方式不能为空");
                return false;
            }
            if (!/^[0-9\-+() ]{7,20}$/.test(phone)) {
                this.$message.error("联系方式格式不正确");
                return false;
            }
            if (this.user.password !== this.user.confirmPassword) {
                this.$message.error("两次密码不一致");
                return false;
            }
            let form = {};
            Object.assign(form, this.user);
            form.password = md5(this.user.password);
            this.request.post("/register", form).then((res) => {
                if (res.code === "200") {
                    this.$message.success("注册成功");
                    this.$router.push("/login");
                } else {
                    this.$message.error(res.msg);
                }
            });
        },
    },
    mounted() {
        
    }
};
</script>

<style scoped>
.wrapper {
    height: 100vh;
    /* background-image: linear-gradient(to top right,#42b983,#B3C0D1); */
    background-color: #006400;
    overflow: auto;
}
.login-box {
    margin: 220px auto;
    padding: 40px;
    width: 450px;
    height: 310px;
    background-color: #ffffff;
    border-radius: 10px;
}
.title {
    text-align: center;
    margin-top: 10px;
    font-size: 25px;
    color: #006400;
}

#bk {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    overflow-y: auto;
    height: 100%;
    background: url("../resource/01.png") center top / cover no-repeat;
}
</style>
