<template>
    <div id="bk" class="wrapper">
        <div class="login-box">
            <div class="title">
                <b style="font-size: 28px"> 登录U次元 </b>
            </div>
            <div style="margin-top: 30px">
                <el-form label-width="70px">
                    <el-form-item label="用户名">
                        <el-input
                            v-model.trim="user.username"
                            aria-required="true"
                        ></el-input>
                    </el-form-item>
                    <el-form-item label="密码" style="margin-top: 25px">
                        <el-input
                            v-model.trim="user.password"
                            show-password
                            aria-required="true"
                            placeholder="6-12位，含字母、数字和特殊符号"
                        ></el-input>
                    </el-form-item>
                    <el-form-item style="text-align: center">
                        <el-button
                            type="success"
                            @click="onSubmit"
                            style="font-size: 22px"
                        > 登录</el-button
                        >
                        <el-button
                            @click="$router.push('/register')"
                            style="font-size: 22px"
                        > 注册</el-button
                        >
                    </el-form-item>
                </el-form>
            </div>
        </div>
    </div>
</template>

<script>
import md5 from "js-md5";

export default {
    name: "Login",
    data() {
        return {
            to: "/", //登陆成功跳转的页面
            user: {},
        };
    },
    created() {
        this.to = this.$route.query.to ? this.$route.query.to : "/";
    },
    mounted() {

    },
    methods: {
        onSubmit() {
            if (this.user.username === "" || this.user.password === "") {
                this.$message.error("账号或密码不能为空");
                return false;
            }
            const passwordRule = /^(?=.*[A-Za-z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{}|;:,.<>?])[A-Za-z\d!@#$%^&*()_+\-=\[\]{}|;:,.<>?]{6,12}$/;
            if (!passwordRule.test(this.user.password)) {
                this.$message.error("密码必须为6-12位，且同时包含字母、数字和特殊符号");
                return false;
            }
            let form = {};
            Object.assign(form, this.user);
            form.password = md5(this.user.password);
            this.request
                .post("/login", form)
                .then((res) => {
                    if (res.code === "200") {
                        localStorage.setItem("user", JSON.stringify(res.data));
                        this.$message.success({
                            message: "登陆成功",
                            showClose: true,
                        });
                        // 根据用户角色决定跳转页面
                        // admin用户跳转到后台管理，其他用户跳转到前台首页
                        let redirectPath = this.to;
                        if (!this.to || this.to === '/') {
                            // 如果没有指定跳转页面，根据角色决定
                            if (res.data.role === 'admin') {
                                redirectPath = '/manage';
                            } else {
                                redirectPath = '/';
                            }
                        }
                        window.location.href = redirectPath;
                    } else {
                        this.$message.error(res.msg);
                    }
                })
                .catch((e) => {
                    if (
                        e.response == undefined ||
                        e.response.data == undefined
                    ) {
                        this.$message({
                            showClose: true,
                            message: e,
                            type: "error",
                            duration: 5000,
                        });
                    } else {
                        this.$message({
                            showClose: true,
                            message: e.response.data,
                            type: "error",
                            duration: 5000,
                        });
                    }
                });
        },
    },
    updated() {

    }
};
</script>

<style scoped>
.wrapper {
    height: 100vh;
    background-color: rgb(161, 202, 220);
    overflow: auto;
}
.login-box {
    margin: 220px auto;
    padding: 40px;
    width: 450px;
    height: 280px;
    background-color: #ffffff;
    border-radius: 10px;
}
.title {
    text-align: center;
    margin: 30px auto;
    font-size: 25px;
}

#bk {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    overflow-y: auto;
    height: 100%;
    background: url("../resource/01.png") center top / cover no-repeat;
}
</style>
